/*
 * pygame_cobol.c — thin SDL2 wrapper callable from GnuCOBOL.
 * Singleton window/renderer; all state is module-internal.
 */
#include <SDL.h>
#include <string.h>
#include <stdint.h>
#include <stdarg.h>
#include <stdio.h>

#define PG_EVENT_NONE        0
#define PG_EVENT_QUIT        1
#define PG_EVENT_KEYDOWN     2
#define PG_EVENT_KEYUP       3
#define PG_EVENT_MOUSEMOTION 4
#define PG_EVENT_MOUSEDOWN   5
#define PG_EVENT_MOUSEUP     6

typedef struct {
    int32_t event_type;
    int32_t key_code;
    int32_t mouse_x;
    int32_t mouse_y;
    int32_t mouse_button;
} pg_event_t;

_Static_assert(sizeof(pg_event_t) == 20, "struct must be 20 bytes for COBOL mapping");

#define PG_MAX_TEXTURES 64

static SDL_Window   *g_window   = NULL;
static SDL_Renderer *g_renderer = NULL;

static struct {
    SDL_Texture *tex;
    int width;
    int height;
} g_textures[PG_MAX_TEXTURES];

static char g_last_error[256] = "";

static void cobol_to_cstr(const char *src, int len, char *dst, int dst_sz) {
    int n = len < dst_sz - 1 ? len : dst_sz - 1;
    memcpy(dst, src, n);
    dst[n] = '\0';
    while (n > 0 && dst[n - 1] == ' ') dst[--n] = '\0';
}

int pg_init(void) {
    return SDL_Init(SDL_INIT_VIDEO | SDL_INIT_TIMER) == 0 ? 0 : -1;
}

void pg_quit(void) {
    for (int i = 0; i < PG_MAX_TEXTURES; i++) {
        if (g_textures[i].tex) {
            SDL_DestroyTexture(g_textures[i].tex);
            g_textures[i].tex = NULL;
        }
    }
    if (g_renderer) { SDL_DestroyRenderer(g_renderer); g_renderer = NULL; }
    if (g_window)   { SDL_DestroyWindow(g_window);     g_window   = NULL; }
    SDL_Quit();
}

int pg_open_window(int w, int h, const char *title, int title_len) {
    char buf[256];
    cobol_to_cstr(title, title_len, buf, sizeof buf);

    g_window = SDL_CreateWindow(buf,
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        w, h, SDL_WINDOW_RESIZABLE);
    if (!g_window) return -1;

    g_renderer = SDL_CreateRenderer(g_window, -1,
        SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (!g_renderer) {
        SDL_DestroyWindow(g_window);
        g_window = NULL;
        return -1;
    }
    return 0;
}

void pg_set_color(int r, int g, int b, int a) {
    if (g_renderer)
        SDL_SetRenderDrawColor(g_renderer, (Uint8)r, (Uint8)g, (Uint8)b, (Uint8)a);
}

void pg_clear(void) {
    if (g_renderer) SDL_RenderClear(g_renderer);
}

void pg_present(void) {
    if (g_renderer) SDL_RenderPresent(g_renderer);
}

void pg_draw_line(int x1, int y1, int x2, int y2) {
    if (g_renderer) SDL_RenderDrawLine(g_renderer, x1, y1, x2, y2);
}

void pg_draw_rect(int x, int y, int w, int h) {
    if (g_renderer) {
        SDL_Rect r = { x, y, w, h };
        SDL_RenderDrawRect(g_renderer, &r);
    }
}

void pg_fill_rect(int x, int y, int w, int h) {
    if (g_renderer) {
        SDL_Rect r = { x, y, w, h };
        SDL_RenderFillRect(g_renderer, &r);
    }
}

int pg_poll_event(pg_event_t *evt) {
    SDL_Event e;
    evt->event_type  = PG_EVENT_NONE;
    evt->key_code    = 0;
    evt->mouse_x     = 0;
    evt->mouse_y     = 0;
    evt->mouse_button = 0;

    if (!SDL_PollEvent(&e)) return 0;

    switch (e.type) {
    case SDL_QUIT:
        evt->event_type = PG_EVENT_QUIT;
        break;
    case SDL_KEYDOWN:
        evt->event_type = PG_EVENT_KEYDOWN;
        evt->key_code   = (int32_t)e.key.keysym.sym;
        break;
    case SDL_KEYUP:
        evt->event_type = PG_EVENT_KEYUP;
        evt->key_code   = (int32_t)e.key.keysym.sym;
        break;
    case SDL_MOUSEMOTION:
        evt->event_type = PG_EVENT_MOUSEMOTION;
        evt->mouse_x    = e.motion.x;
        evt->mouse_y    = e.motion.y;
        break;
    case SDL_MOUSEBUTTONDOWN:
        evt->event_type  = PG_EVENT_MOUSEDOWN;
        evt->mouse_x     = e.button.x;
        evt->mouse_y     = e.button.y;
        evt->mouse_button = e.button.button;
        break;
    case SDL_MOUSEBUTTONUP:
        evt->event_type  = PG_EVENT_MOUSEUP;
        evt->mouse_x     = e.button.x;
        evt->mouse_y     = e.button.y;
        evt->mouse_button = e.button.button;
        break;
    default:
        return 0;
    }
    return 1;
}

void pg_delay(int ms) {
    SDL_Delay((Uint32)ms);
}

int pg_get_ticks(void) {
    return (int)SDL_GetTicks();
}

void pg_set_title(const char *title, int title_len) {
    if (g_window) {
        char buf[256];
        cobol_to_cstr(title, title_len, buf, sizeof buf);
        SDL_SetWindowTitle(g_window, buf);
    }
}

/* ── image loading ──────────────────────────────────────── */

static void set_error(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(g_last_error, sizeof g_last_error, fmt, ap);
    va_end(ap);
}

int pg_load_image(const char *path, int path_len) {
    char buf[512];
    cobol_to_cstr(path, path_len, buf, sizeof buf);

    if (!g_renderer) {
        set_error("No renderer - call pg_open_window first");
        return -1;
    }

    int slot = -1;
    for (int i = 0; i < PG_MAX_TEXTURES; i++) {
        if (!g_textures[i].tex) { slot = i; break; }
    }
    if (slot < 0) {
        set_error("Too many loaded images (max %d)", PG_MAX_TEXTURES);
        return -1;
    }

    SDL_Surface *surf = SDL_LoadBMP(buf);
    if (!surf) {
        set_error("Cannot load '%s': %s", buf, SDL_GetError());
        return -1;
    }

    SDL_Texture *tex = SDL_CreateTextureFromSurface(g_renderer, surf);
    int w = surf->w, h = surf->h;
    SDL_FreeSurface(surf);

    if (!tex) {
        set_error("Cannot create texture: %s", SDL_GetError());
        return -1;
    }

    g_textures[slot].tex    = tex;
    g_textures[slot].width  = w;
    g_textures[slot].height = h;
    g_last_error[0] = '\0';
    return slot + 1;
}

int pg_image_width(int handle) {
    if (handle < 1 || handle > PG_MAX_TEXTURES) return 0;
    if (!g_textures[handle - 1].tex) return 0;
    return g_textures[handle - 1].width;
}

int pg_image_height(int handle) {
    if (handle < 1 || handle > PG_MAX_TEXTURES) return 0;
    if (!g_textures[handle - 1].tex) return 0;
    return g_textures[handle - 1].height;
}

void pg_draw_image(int handle, int x, int y) {
    if (handle < 1 || handle > PG_MAX_TEXTURES) return;
    int idx = handle - 1;
    if (!g_textures[idx].tex || !g_renderer) return;
    SDL_Rect dst = { x, y, g_textures[idx].width, g_textures[idx].height };
    SDL_RenderCopy(g_renderer, g_textures[idx].tex, NULL, &dst);
}

void pg_draw_image_sized(int handle, int x, int y, int w, int h) {
    if (handle < 1 || handle > PG_MAX_TEXTURES) return;
    int idx = handle - 1;
    if (!g_textures[idx].tex || !g_renderer) return;
    SDL_Rect dst = { x, y, w, h };
    SDL_RenderCopy(g_renderer, g_textures[idx].tex, NULL, &dst);
}

void pg_free_image(int handle) {
    if (handle < 1 || handle > PG_MAX_TEXTURES) return;
    int idx = handle - 1;
    if (g_textures[idx].tex) {
        SDL_DestroyTexture(g_textures[idx].tex);
        g_textures[idx].tex    = NULL;
        g_textures[idx].width  = 0;
        g_textures[idx].height = 0;
    }
}

void pg_get_error(char *buf, int buf_len) {
    int n = (int)strlen(g_last_error);
    if (n > buf_len) n = buf_len;
    memcpy(buf, g_last_error, n);
    for (int i = n; i < buf_len; i++) buf[i] = ' ';
}

