116	int pg_poll_event(pg_event_t *evt) {
117	    SDL_Event e;
118	    evt->event_type  = PG_EVENT_NONE;
119	    evt->key_code    = 0;
120	    evt->mouse_x     = 0;
121	    evt->mouse_y     = 0;
122	    evt->mouse_button = 0;
123	
124	    if (!SDL_PollEvent(&e)) return 0;
125	
126	    switch (e.type) {
127	    case SDL_QUIT:
128	        evt->event_type = PG_EVENT_QUIT;
129	        break;
130	    case SDL_KEYDOWN:
131	        evt->event_type = PG_EVENT_KEYDOWN;
132	        evt->key_code   = (int32_t)e.key.keysym.sym;
133	        break;
134	    case SDL_KEYUP:
135	        evt->event_type = PG_EVENT_KEYUP;
136	        evt->key_code   = (int32_t)e.key.keysym.sym;
137	        break;
138	    case SDL_MOUSEMOTION:
139	        evt->event_type = PG_EVENT_MOUSEMOTION;
140	        evt->mouse_x    = e.motion.x;
141	        evt->mouse_y    = e.motion.y;
142	        break;
143	    case SDL_MOUSEBUTTONDOWN:
144	        evt->event_type  = PG_EVENT_MOUSEDOWN;
145	        evt->mouse_x     = e.button.x;
146	        evt->mouse_y     = e.button.y;
147	        evt->mouse_button = e.button.button;
148	        break;
149	    case SDL_MOUSEBUTTONUP:
150	        evt->event_type  = PG_EVENT_MOUSEUP;
151	        evt->mouse_x     = e.button.x;
152	        evt->mouse_y     = e.button.y;
153	        evt->mouse_button = e.button.button;
154	        break;
155	    default:
