186	int pg_load_image(const char *path, int path_len) {
187	    char buf[512];
188	    cobol_to_cstr(path, path_len, buf, sizeof buf);
189	
190	    if (!g_renderer) {
191	        set_error("No renderer - call pg_open_window first");
192	        return -1;
193	    }
194	
195	    int slot = -1;
196	    for (int i = 0; i < PG_MAX_TEXTURES; i++) {
197	        if (!g_textures[i].tex) { slot = i; break; }
198	    }
199	    if (slot < 0) {
200	        set_error("Too many loaded images (max %d)", PG_MAX_TEXTURES);
201	        return -1;
202	    }
203	
204	    FILE *probe = fopen(buf, "rb");
205	    if (!probe) {
206	        set_error("Cannot open '%s': %s", buf, strerror(errno));
207	        return -1;
208	    }
209	    fclose(probe);
210	
211	    SDL_Surface *surf = SDL_LoadBMP(buf);
212	    if (!surf) {
213	        set_error("Cannot load '%s': %s", buf, SDL_GetError());
214	        return -1;
215	    }
216	
217	    SDL_Texture *tex = SDL_CreateTextureFromSurface(g_renderer, surf);
218	    int w = surf->w, h = surf->h;
219	    SDL_FreeSurface(surf);
220	
221	    if (!tex) {
222	        set_error("Cannot create texture: %s", SDL_GetError());
223	        return -1;
224	    }
225	
226	    g_textures[slot].tex    = tex;
227	    g_textures[slot].width  = w;
228	    g_textures[slot].height = h;
229	    g_last_error[0] = '\0';
230	    return slot + 1;
231	}
