245	void pg_draw_image(int handle, int x, int y) {
246	    if (handle < 1 || handle > PG_MAX_TEXTURES) return;
247	    int idx = handle - 1;
248	    if (!g_textures[idx].tex || !g_renderer) return;
249	    SDL_Rect dst = { x, y, g_textures[idx].width, g_textures[idx].height };
250	    SDL_RenderCopy(g_renderer, g_textures[idx].tex, NULL, &dst);
251	}
