261	void pg_free_image(int handle) {
262	    if (handle < 1 || handle > PG_MAX_TEXTURES) return;
263	    int idx = handle - 1;
264	    if (g_textures[idx].tex) {
265	        SDL_DestroyTexture(g_textures[idx].tex);
266	        g_textures[idx].tex    = NULL;
267	        g_textures[idx].width  = 0;
268	        g_textures[idx].height = 0;
269	    }
270	}
