    int n = len < dst_sz - 1 ? len : dst_sz - 1;
    memcpy(dst, src, n);
    dst[n] = '\0';
    while (n > 0 && dst[n - 1] == ' ') dst[--n] = '\0';
}

int pg_init(void) {
    return SDL_Init(SDL_INIT_VIDEO | SDL_INIT_TIMER) == 0 ? 0 : -1;
}

int pg_quit(void) {
    for (int i = 0; i < PG_MAX_TEXTURES; i++) {
        if (g_textures[i].tex) {
            SDL_DestroyTexture(g_textures[i].tex);
            g_textures[i].tex = NULL;
        }
    }
    if (g_renderer) { SDL_DestroyRenderer(g_renderer); g_renderer = NULL; }
    if (g_window)   { SDL_DestroyWindow(g_window);     g_window   = NULL; }
    SDL_Quit();
    return 0;
}

int pg_open_window(int w, int h, const char *title, int title_len) {
    char buf[256];
    cobol_to_cstr(title, title_len, buf, sizeof buf);

    g_window = SDL_CreateWindow(buf,
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        w, h, SDL_WINDOW_RESIZABLE);
    if (!g_window) return -1;

    g_renderer = SDL_CreateRenderer(g_window, -1,
        SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (!g_renderer) {
        SDL_DestroyWindow(g_window);
        g_window = NULL;
        return -1;
    }
    return 0;
}

int pg_set_color(int r, int g, int b, int a) {
    if (g_renderer)
        SDL_SetRenderDrawColor(g_renderer, (Uint8)r, (Uint8)g, (Uint8)b, (Uint8)a);
    return 0;
}

int pg_clear(void) {
    if (g_renderer) SDL_RenderClear(g_renderer);
    return 0;
}

int pg_present(void) {
    if (g_renderer) SDL_RenderPresent(g_renderer);
    return 0;
}

int pg_draw_line(int x1, int y1, int x2, int y2) {
    if (g_renderer) SDL_RenderDrawLine(g_renderer, x1, y1, x2, y2);
    return 0;
}

int pg_draw_rect(int x, int y, int w, int h) {
    if (g_renderer) {
        SDL_Rect r = { x, y, w, h };
        SDL_RenderDrawRect(g_renderer, &r);
    }
    return 0;
}

int pg_fill_rect(int x, int y, int w, int h) {
