int pg_poll_event(pg_event_t *evt) {
    SDL_Event e;
    evt->event_type  = PG_EVENT_NONE;
    evt->key_code    = 0;
    evt->mouse_x     = 0;
    evt->mouse_y     = 0;
    evt->mouse_button = 0;

